import React from 'react';
import './App.css';

function App() {
  return (
    <div className="App">
      <header className="App-header">
        <h1>Welcome to TruthGuard</h1>
        <p>Your trusted content verification platform</p>
      </header>
    </div>
  );
}

export default App;
